export const KEY_RE = /^[a-z][a-z0-9_]*(\.[a-z][a-z0-9_]*){2,3}$/;

/**
 * Token syntax, byte-identical to docgen/index.ts:376, so an admin who has
 * edited a PDF template at #documents already knows it.
 */
export const TOKEN_RE = /\{\{\s*([\w.]+)\s*\}\}/g;

/**
 * A line that is exactly `emoji *Label:* {{token}}` - the output shape of
 * fmt.fact(). A variable alone in a fact row ALWAYS drops the row when it has
 * no value, whatever its declared miss policy says, because that is what
 * fmt.fact() does (returns '') and what every existing block relies on. A
 * fallback belongs in prose ("Nurse your nurse is on her way"), never in a
 * label column ("Nurse: your nurse").
 */
export const FACT_ROW_RE = /^\s*(?:[^\s\w]+\s+)?\*[^*\n]+:\*\s*\{\{\s*[\w.]+\s*\}\}\s*$/u;

