/** Hindi needs roughly a quarter more characters for the same content. */
export function maxCharsFor(def, lang) {
  const n = lang === 'hi' ? Math.round(def.max_chars * 1.25) : def.max_chars;
  return Math.min(n, PUBLISH_CAP[def.surface]);
}

/** Every distinct token in a body, in order of first appearance. */
export function tokensOf(body) {
  const out = [];
  const re = new RegExp(TOKEN_RE.source, 'g');
  let m;
  while ((m = re.exec(String(body ?? ''))) !== null) {
    if (!out.includes(m[1])) out.push(m[1]);
  }
  return out;
}

/** Split a key into its segments, or null when the shape is wrong. */
export function parseKey(key) {
  const k = String(key ?? '');
  if (k.length > 64 || !KEY_RE.test(k)) return null;
  const p = k.split('.');
  return { stage: p[0], event: p[1], audience: p[2], variant: p[3] ?? null };
}

/**
 * Is this Hindi actually Hindi? A single-codepoint test passes
 * "Aapka session kal hai. आ", which is exactly the transliteration this is
 * meant to catch. Strip tokens, brand Latin and emoji, then require 80 percent
 * of the remaining LETTERS to be Devanagari, over a minimum of 8 letters.
 */
export function isDevanagari(hi) {
  const stripped = String(hi ?? '')
    .replace(new RegExp(TOKEN_RE.source, 'g'), ' ')
    .replace(/\b(Carcinome|WhatsApp|UPI|PICC|IV|Jarurat|Home Care|DONE|STATUS|YES|NO|NEXT|JOIN|MUTE|STOP|CANCEL)\b/g, ' ')
    .replace(/\p{Extended_Pictographic}/gu, ' ');
  const letters = Array.from(stripped).filter((ch) => /\p{L}/u.test(ch));
  if (letters.length < 8) return false;
  const dev = letters.filter((ch) => /[ऀ-ॿ]/.test(ch)).length;
  return dev / letters.length >= 0.8;
}

/**
 * doctor.ts:78 looksFramed, mirrored exactly. A framed body (emoji then a bold
 * title alone on line 1) BYPASSES the doctor/POC envelope entirely, which
 * means it also loses the case code and the patient name the envelope adds.
 * Flipping this on a mirror key silently rewrites 18 downstream messages, so
 * the publish validator asserts the published body keeps the same answer as
 * the registry default rather than banning framing outright: several keys are
 * framed ON PURPOSE and must stay that way.
 */
export function looksFramed(raw) {
  const first = String(raw ?? '').split('\n').find((l) => l.trim().length);
  if (!first) return false;
  const head = first.trim();
  // TWO first-line shapes count as an already-built block, because both are in
  // the registry today and only the first was ever recognised:
  //
  //   "🩺 *Nurse accepted an offer*"      a bold title, alone
  //   "*Arrival verified* · CASE-2026-12"  a bold title plus a trailer
  //
  // The second shape is what made this a real defect rather than a style note.
  // Keys carrying it are declared mirror_raw and documented as "framed on
  // purpose, the log wrapper is bypassed", but they failed this test, so
  // notifyPoc wrapped them in the 📔 envelope a second time and the POC read
  // two titles, the case code twice and the patient name twice.
  //
  // The trailer must be fenced off by an explicit separator. Widening this to
  // "anything after the bold run" would swallow an ordinary sentence that
  // merely opens with a bold word, and a false positive here DELETES the case
  // code and the patient name for every reader of all 18 mirror sites, which
  // is far worse than the duplication it is fixing.
  //
  // Only the middle dot and the pipe are listed. No dash belongs here: fmt
  // dashes() folds every dash-like codepoint to a plain hyphen long before this
  // runs, and a plain hyphen is too common inside real titles to be a fence.
  return /^[^\p{L}\p{N}]*\s*\*[^*\n]+\*\s*$/u.test(head)
    || /^[^\p{L}\p{N}]*\s*\*[^*\n]+\*\s*[·|]\s*\S/u.test(head);
}

